import { useEffect, useState } from "react";
import axios from "axios";
import { useParams, useNavigate } from "react-router-dom";
import Accordion from "react-bootstrap/Accordion";
import "bootstrap/dist/css/bootstrap.min.css";
import EmployeeItem from "./EmployeeItem";

function EmployeeList() {
  const { departmentId } = useParams();
  const navigate = useNavigate();

  const [employees, setEmployees] = useState([]);
  const [workons, setWorkons] = useState([]);
  const [projects, setProjects] = useState([]);

  useEffect(() => {
    const fetchData = async () => {
      const [empRes, workRes, proRes] = await Promise.all([
        axios.get("http://localhost:9999/employees"),
        axios.get("http://localhost:9999/workons"),
        axios.get("http://localhost:9999/projects"),
      ]);
      setEmployees(empRes.data);
      setWorkons(workRes.data);
      setProjects(proRes.data);
    };
    fetchData();
  }, []);

  const filteredEmployees = employees.filter(
    (emp) => String(emp.depId) === String(departmentId)
  );

  const getProjectName = (proId) => {
    const project = projects.find((p) => String(p.id) === String(proId));
    return project ? project.proName : "";
  };

  const getWorkons = (empId) =>
    workons.filter((w) => String(w.empId) === String(empId));

  return (
    <div style={{ padding: "20px" }}>
      <h2 style={{ textAlign: "center" }}>COMPANY MANAGEMENT</h2>
      <button
        onClick={() => navigate("/")}
        style={{
          marginBottom: "16px",
          backgroundColor: "#6c757d",
          color: "white",
          border: "none",
          padding: "6px 14px",
          borderRadius: "4px",
          cursor: "pointer",
        }}
      >
        ← Back to Department List
      </button>
      <h3>Employee List</h3>
      <Accordion>
        {filteredEmployees.map((emp, index) => (
          <EmployeeItem
            key={emp.id}
            emp={emp}
            index={index}
            works={getWorkons(emp.id)}
            getProjectName={getProjectName}
          />
        ))}
      </Accordion>
    </div>
  );
}

export default EmployeeList;
